    "params": [
      {
        "name": "view",
        "in": "query",
        "type": "enum",
        "enum": [
          "all",
          "organic"
        ],
        "default": "all",
        "desc": "organic leaves out providers in the on-chain wash registry plus our confirmed clusters; all keeps every provider"
      }
    ],
    "example": "/staking/pools",
    "page": "/staking",
    "prompt": "Which Antseed provider pools hold the most stake and power, and what do they earn?",
